// dark lines from the tile's corners on the map up to the lifted tile
const n = Math.round(Math.sqrt(npoints(1)));
for (const k of [0, n - 1, n * (n - 1), n * n - 1]) {
  const p = point(1, 'P', k), a = addpoint(0, p), b = addpoint(0, [p[0], p[1] + relief + map_size * 0.18, p[2]]);
  addprim(0, 'polyline', [a, b]);
  setpointattrib(0, 'Cd', a, [0.12, 0.1, 0.09]); setpointattrib(0, 'Cd', b, [0.12, 0.1, 0.09]);
}

// colours from the heights (absolute, so the tile and the map share them): green lowland, pale upland, red-brown
// escarpment faces, blue water; a dark frame on the map marks the tile's spot
const h = clamp(@height / relief, 0, 1), steep = 1 - smoothstep(0.62, 0.82, @N[1]);
let c = mix([0.30, 0.43, 0.19], [0.66, 0.58, 0.40], smoothstep(0.25, 0.8, h));
c = mix(c, [0.50, 0.36, 0.27], steep);
c = mix(c, [0.10, 0.27, 0.42], @water);
const lo = detail(1, 'crop_core_min'), hi = detail(1, 'crop_core_max'), e = map_size / 200; // the tile's bounds
const inside = @P.x > lo[0] - e && @P.x < hi[0] + e && @P.z > lo[1] - e && @P.z < hi[1] + e;
const frame = inside && (@P.x < lo[0] + e || @P.x > hi[0] - e || @P.z < lo[1] + e || @P.z > hi[1] - e);
@Cd = frame && @P.y < relief * 1.05 ? [0.12, 0.1, 0.09] : c;
